import React, { useState, useEffect } from 'react';
import { Button } from 'react-bootstrap';

export default function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');

  const fetchOrders = async () => {
    try {
      const res = await fetch('http://localhost/api/comandes', {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Error al obtenir les comandes');
      const data = await res.json();
      setOrders(data.dades || []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquesta comanda?')) return;
    try {
      const res = await fetch(`http://localhost/api/comandes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('No s\'ha pogut eliminar la comanda');
      fetchOrders();
    } catch (err) {
      alert(err.message);
    }
  };

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div className="row">
      {orders.map(order => (
        <div key={order.id} className="col-md-6 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">
                Client: {order.client?.nom} / Proveïdor: {order.proveidor?.nom}
              </h5>
              <p className="card-text"><strong>Tipus:</strong> {order.tipus}</p>
              <p className="card-text"><strong>Data:</strong> {new Date(order.data).toLocaleDateString('ca-ES')}</p>
              <Button variant="danger" onClick={() => handleDelete(order.id)}>Eliminar</Button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
